internal sealed class SongesWindow:Window {
 readonly string file;readonly Stopwatch clock=Stopwatch.StartNew();readonly DispatcherTimer timer;SongesRun run;SongesOcr reader;SongesGameWindow game;bool armed,reading,closed,testing;int generation;long lastRead=-3000,lastSave;TextBlock total,room,combat,depth,status,summary,history,official,previousRuns;ComboBox games;Button arm;string notice="Sélectionnez la fenêtre DOFUS, puis activez la lecture locale.";
 internal SongesWindow(string root,bool test=false){testing=test;file=Path.Combine(root,"songes-run.json");run=ReadState(file);Title="Songes · run complète";Width=390;Height=620;MinWidth=350;MinHeight=500;MaxWidth=1000;MaxHeight=1200;Topmost=true;WindowStyle=WindowStyle.None;AllowsTransparency=true;Background=Brushes.Transparent;ResizeMode=ResizeMode.CanResizeWithGrip;FontFamily=new FontFamily("Segoe UI");Foreground=CompanionWindow.Ink;Resources=(ResourceDictionary)System.Windows.Markup.XamlReader.Parse(CompanionWindow.Styles);var frame=new Border{Background=CompanionWindow.BackgroundColor,BorderBrush=CompanionWindow.Surface,BorderThickness=new Thickness(1),CornerRadius=new CornerRadius(18),Padding=new Thickness(20)};Content=frame;var grid=new Grid();grid.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});grid.RowDefinitions.Add(new RowDefinition());frame.Child=grid;var header=new DockPanel();var close=CompanionWindow.Button("×",Close);DockPanel.SetDock(close,Dock.Right);header.Children.Add(close);var title=CompanionWindow.Text("SONGES · RUN COMPLÈTE",11,true);title.Cursor=Cursors.SizeAll;title.MouseLeftButtonDown+=delegate(object s,MouseButtonEventArgs e){if(e.LeftButton==MouseButtonState.Pressed&&!testing)DragMove();};header.Children.Add(title);grid.Children.Add(header);var body=new StackPanel();var scroll=new ScrollViewer{Content=body,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};Grid.SetRow(scroll,1);grid.Children.Add(scroll);
 depth=CompanionWindow.Text("",21);depth.FontFamily=new FontFamily("Georgia");body.Children.Add(depth);total=CompanionWindow.Text("",32);total.Foreground=CompanionWindow.Accent;body.Children.Add(CompanionWindow.Text("RUN COMPLÈTE",10,true));body.Children.Add(total);body.Children.Add(CompanionWindow.Text("TEMPS DANS CETTE SALLE",10,true));room=CompanionWindow.Text("",28);body.Children.Add(room);body.Children.Add(CompanionWindow.Text("COMBAT EN COURS",10,true));combat=CompanionWindow.Text("",24);body.Children.Add(combat);official=CompanionWindow.Text("",12,true);body.Children.Add(official);previousRuns=CompanionWindow.Text("",11,true);body.Children.Add(new Expander{Header="Runs précédentes",Content=previousRuns,Foreground=CompanionWindow.Ink});LoadHistory();summary=CompanionWindow.Text("",12,true);body.Children.Add(summary);history=CompanionWindow.Text("",11,true);body.Children.Add(new Expander{Header="Temps par salle",Content=history,Foreground=CompanionWindow.Ink});status=CompanionWindow.Text("",11,true);body.Children.Add(status);
 games=new ComboBox{MinHeight=34,DisplayMemberPath=""};body.Children.Add(games);body.Children.Add(CompanionWindow.Button("Actualiser les fenêtres DOFUS",RefreshGames));arm=CompanionWindow.Button("Activer la détection",Toggle,true);body.Children.Add(arm);var manual=new WrapPanel();manual.Children.Add(CompanionWindow.Button("Début combat",()=>{run.Resume(clock.ElapsedMilliseconds);run.BeginFight(clock.ElapsedMilliseconds);notice="Combat démarré manuellement.";Save();Update();}));manual.Children.Add(CompanionWindow.Button("Victoire",()=>{if(!run.State.combat){notice="Aucun combat à terminer.";Update();return;}run.Resume(clock.ElapsedMilliseconds);run.EndFight(clock.ElapsedMilliseconds,true);notice="Victoire enregistrée manuellement.";Save();Update();}));manual.Children.Add(CompanionWindow.Button("Défaite",()=>{if(!run.State.combat){notice="Aucun combat à terminer.";Update();return;}run.Resume(clock.ElapsedMilliseconds);run.EndFight(clock.ElapsedMilliseconds,false);notice="Défaite enregistrée, sans valider la salle.";Save();Update();}));body.Children.Add(manual);
 var correct=new WrapPanel();correct.Children.Add(CompanionWindow.Button("Corriger la salle",Correct));correct.Children.Add(CompanionWindow.Button("Temps officiel",CorrectOfficial));correct.Children.Add(CompanionWindow.Button("Terminer la run",()=>{run.Finish(clock.ElapsedMilliseconds);armed=false;generation++;Save();Update();}));correct.Children.Add(CompanionWindow.Button("Nouvelle run",Reset));body.Children.Add(correct);body.Children.Add(CompanionWindow.Text("Départ : FIN DE TOUR · arrêt : VICTOIRE / DÉFAITE. La profondeur fournit la salle ; les combats sont comptés séparément. Le chrono global continue aux marchés et bonus. La run s’arrête après une victoire détectée en salle 26, ou avec Terminer la run.",10,true));body.Children.Add(CompanionWindow.Text("La fenêtre DOFUS doit être au premier plan et les repères visibles. Les images sont analysées en mémoire, sans enregistrement ni envoi. Lecture expérimentale : gardez les corrections manuelles à portée.",10,true));timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(250)};timer.Tick+=async delegate{run.Tick(clock.ElapsedMilliseconds);Update();if(armed&&!reading&&clock.ElapsedMilliseconds-lastRead>=1000)await Scan();if(!testing&&run.State.started&&clock.ElapsedMilliseconds-lastSave>10000)Save();};Loaded+=delegate{if(!testing){Left=Math.Max(SystemParameters.WorkArea.Left,SystemParameters.WorkArea.Right-Width-12);Top=SystemParameters.WorkArea.Top+32;RefreshGames();timer.Start();}};Closed+=delegate{closed=true;armed=false;generation++;timer.Stop();run.Pause(clock.ElapsedMilliseconds);if(!testing)Save();};Update();}
 static SongesRun ReadState(string file){if(!File.Exists(file))return new SongesRun(new SongesState());if(new FileInfo(file).Length>1024*1024)throw new InvalidDataException("Historique Songes trop volumineux.");var state=Store.Json.Deserialize<SongesState>(File.ReadAllText(file));if(state==null)throw new InvalidDataException("Sauvegarde Songes invalide. Le fichier existant est conservé.");return new SongesRun(state);}
 void RefreshGames(){if(armed)return;games.ItemsSource=SongesCapture.List();games.SelectedIndex=games.Items.Count==0?-1:0;}
 void Toggle(){if(armed){armed=false;generation++;run.Pause(clock.ElapsedMilliseconds);notice="Lecture arrêtée, chronomètre en pause.";Save();Update();return;}if(run.State.finished&&run.State.officialMs>=0){notice="La run est terminée. Utilisez Nouvelle run.";Update();return;}var selected=games.SelectedItem as SongesGameWindow;if(selected==null){notice="Aucune fenêtre DOFUS sélectionnée. Lancez le jeu puis actualisez la liste.";Update();return;}game=selected;try{if(reader==null)reader=new SongesOcr();armed=true;generation++;run.Resume(clock.ElapsedMilliseconds);notice="Lecture activée. Revenez dans DOFUS : attente du premier tour.";}catch(Exception ex){notice=ex.Message;}Update();}
 async Task Scan(){reading=true;lastRead=clock.ElapsedMilliseconds;int current=generation;try{var frame=SongesCapture.Frame(game);if(frame==null){notice="Jeu masqué ou non sélectionné : détection suspendue. Le temps global continue si la run a commencé.";run.ResetDetection();return;}using(frame){var observation=await Task.Run(async()=>await reader.Read(frame));if(closed||current!=generation||!armed)return;int previousCount=run.State.fights.Count,previousFloor=run.State.floor;bool previousCombat=run.State.combat;if(observation.OfficialMs.HasValue)run.ObserveOfficial(clock.ElapsedMilliseconds,observation.OfficialMs.Value,observation.SummaryVictory);else run.ResetOfficialDetection();run.Observe(clock.ElapsedMilliseconds,observation.EndTurn,observation.Victory,observation.Defeat,observation.Depth);if(previousCount!=run.State.fights.Count||previousFloor!=run.State.floor||previousCombat!=run.State.combat)Save();notice="Lecture active · "+(observation.Depth.HasValue?"profondeur "+observation.Depth.Value:"profondeur non lue")+" · "+(observation.Victory?"victoire":observation.Defeat?"défaite":observation.EndTurn?"combat":"hors combat");if(run.State.finished){notice=run.State.officialMs>=0?"Songe terminé · temps officiel enregistré.":"Combat final terminé. Attente de la fenêtre Songe terminé pour le temps officiel.";if(run.State.officialMs>=0){armed=false;generation++;}Save();}}}catch(Exception ex){notice="Lecture indisponible : "+ex.Message+" Les commandes manuelles restent utilisables.";run.ResetDetection();}finally{reading=false;if(!closed)Update();}}
 void Update(){var s=run.State;depth.Text="Salle "+(s.floor==0?"—":s.floor.ToString())+" / 26";total.Text=SongesRun.Duration(s.totalMs);official.Text=s.officialMs<0?"Temps officiel : en attente du bilan Songe terminé.":"DOFUS : "+SongesRun.Duration(s.officialMs)+" · "+s.outcome+"\nÉcart mesuré − officiel : "+(s.totalMs>=s.officialMs?"+":"−")+SongesRun.Duration(Math.Abs(s.totalMs-s.officialMs));room.Text=SongesRun.Duration(s.finished&&s.rooms.Count>0?s.rooms.Last().milliseconds:s.roomMs);history.Text=s.rooms.Count==0?"Aucune salle terminée.":String.Join("\n",s.rooms.Select(r=>"Salle "+(r.floor==0?"non lue":r.floor.ToString())+" · "+SongesRun.Duration(r.milliseconds)));combat.Text=s.combat?SongesRun.Duration(s.combatMs):s.finished?"Run terminée":"En attente";int victories=s.fights.Count(f=>f.result=="victoire");summary.Text=victories+" victoires · "+s.fights.Count(f=>f.result!="victoire")+" défaites\nTemps en combat : "+SongesRun.Duration(s.fights.Sum(f=>f.milliseconds)+s.combatMs)+"\nMoyenne : "+SongesRun.Duration(s.fights.Count==0?0:s.fights.Sum(f=>f.milliseconds)/s.fights.Count);status.Text=(s.paused?"EN PAUSE · ":"")+notice;arm.Content=armed?"Arrêter la lecture / pause":"Activer / reprendre la détection";games.IsEnabled=!armed;}
 void Save(){if(testing)return;try{Directory.CreateDirectory(Path.GetDirectoryName(file));string temp=file+".tmp";File.WriteAllText(temp,Store.Json.Serialize(run.State),new System.Text.UTF8Encoding(false));if(File.Exists(file))File.Replace(temp,file,file+".previous");else File.Move(temp,file);lastSave=clock.ElapsedMilliseconds;}catch(Exception ex){notice="Le chrono fonctionne, mais la sauvegarde a échoué : "+ex.Message;}}
 void Reset(){if(MessageBox.Show(this,"Commencer une nouvelle run ? Le bilan actuel sera archivé.","Songes",MessageBoxButton.YesNo)!=MessageBoxResult.Yes)return;armed=false;generation++;run.Pause(clock.ElapsedMilliseconds);Save();if(File.Exists(file))File.Copy(file,file+"."+DateTime.Now.ToString("yyyyMMdd-HHmmss-fff")+".json");run=new SongesRun(new SongesState());notice="Nouvelle run : activez la lecture ou démarrez un combat manuellement.";Save();LoadHistory();Update();}
 void Correct(){var dialog=new Window{Title="Corriger la salle",Width=340,Height=230,Owner=this,WindowStartupLocation=WindowStartupLocation.CenterOwner,Background=CompanionWindow.BackgroundColor};dialog.Resources=Resources;var panel=new StackPanel{Margin=new Thickness(20)};dialog.Content=panel;panel.Children.Add(CompanionWindow.Text("Profondeur / numéro de salle"));var input=CompanionWindow.Combo(Enumerable.Range(0,27).Select(i=>i.ToString()),run.State.floor);panel.Children.Add(input);panel.Children.Add(CompanionWindow.Button("Enregistrer",()=>{run.SetFloor(clock.ElapsedMilliseconds,input.SelectedIndex);Save();Update();dialog.Close();},true));dialog.ShowDialog();}
 void LoadHistory(){if(previousRuns==null)return;try{string directory=Path.GetDirectoryName(file);previousRuns.Text=!Directory.Exists(directory)?"Aucune run archivée.":String.Join("\n\n",Directory.GetFiles(directory,"songes-run.json.*.json").OrderByDescending(f=>f).Take(10).Select(f=>{var s=Store.Json.Deserialize<SongesState>(File.ReadAllText(f));return s==null?"Archive illisible":File.GetLastWriteTime(f).ToString("dd/MM HH:mm")+" · "+(String.IsNullOrEmpty(s.outcome)?"résultat non lu":s.outcome)+"\nOfficiel : "+(s.officialMs<0?"non lu":SongesRun.Duration(s.officialMs))+" · Mesuré : "+SongesRun.Duration(s.totalMs);}));if(String.IsNullOrWhiteSpace(previousRuns.Text))previousRuns.Text="Aucune run archivée.";}catch{previousRuns.Text="Impossible de lire une archive. Les fichiers sont conservés.";}}
 void CorrectOfficial(){if(!run.State.started){notice="Démarrez une run avant de saisir le bilan.";Update();return;}var dialog=new Window{Title="Bilan officiel DOFUS",Width=350,Height=270,Owner=this,WindowStartupLocation=WindowStartupLocation.CenterOwner,Background=CompanionWindow.BackgroundColor};dialog.Resources=Resources;var panel=new StackPanel{Margin=new Thickness(20)};dialog.Content=panel;panel.Children.Add(CompanionWindow.Text("Temps affiché par DOFUS (ex. 12:48)"));var input=new TextBox{Text="",MinHeight=32};panel.Children.Add(input);var outcome=CompanionWindow.Combo(new[]{"Victoire","Défaite"},0);panel.Children.Add(outcome);var error=CompanionWindow.Text("",11,true);panel.Children.Add(error);panel.Children.Add(CompanionWindow.Button("Enregistrer le bilan",()=>{long? ms=SongesOcr.ParseTime(input.Text.Trim());if(!ms.HasValue){error.Text="Utilisez minutes:secondes ou heures:minutes:secondes.";return;}run.SetOfficial(clock.ElapsedMilliseconds,ms.Value,outcome.SelectedIndex==0);armed=false;generation++;Save();Update();dialog.Close();},true));dialog.ShowDialog();}
 internal void Render(string path){var element=(FrameworkElement)Content;element.Width=Width;element.Height=Height;element.Measure(new Size(Width,Height));element.Arrange(new Rect(0,0,Width,Height));element.UpdateLayout();var bitmap=new System.Windows.Media.Imaging.RenderTargetBitmap((int)Width,(int)Height,96,96,PixelFormats.Pbgra32);bitmap.Render(element);var encoder=new System.Windows.Media.Imaging.PngBitmapEncoder();encoder.Frames.Add(System.Windows.Media.Imaging.BitmapFrame.Create(bitmap));using(var f=File.Create(path))encoder.Save(f);}
